            code: str(rd(r, 'code', 'employeeCode', 'entityId')),
            name: str(rd(r, 'name', 'employeeName')),
            department: str(rd(r, 'departmentName', 'department')),
            plan: str(rd(r, 'plan', 'planId')),
            planName: str(rd(r, 'planName', 'planCode')),
            quota: numv(rd(r, 'quota')),
            base: numv(rd(r, 'base')),
