            earned: numv(rd(r, 'earned')),
            override: numv(rd(r, 'override', 'overrideAmount', 'override_amount')),
            adjustments: numv(rd(r, 'adjustments', 'adjustmentAmount')),
            capped: numv(rd(r, 'capped')),
