    const TEMPLATE_HEADERS = ['doc_no', 'line_no', 'tran_type', 'date', 'customer_code', 'customer_name', 'customer_category', 'item_code', 'revenue', 'cost', 'qty', 'employee', 'department', 'class', 'location', 'collected_date', 'collected_amount', 'item_type', 'item_group', 'customer_type'];
    const TEMPLATE_SAMPLE = ['HD0001', '1', 'I', '2026-10-15', 'KH001', 'Customer A', 'Retail', 'SP001', '15000000', '11000000', '10', 'NV001', '', '', '', '', '', 'InvtPart', 'Dien may', 'N'];
    const templateCsv = () => `﻿${TEMPLATE_HEADERS.join(',')}\r\n${TEMPLATE_SAMPLE.join(',')}\r\n`;
    const headKey = (h) => fold(h)
        .replace(/[_\-./]+/g, ' ')
        .replace(/[^a-z0-9 ]/g, ' ')
        .replace(/\s+/g, ' ')
